  'contour.fromMask.retrieval': '外轮廓只取最外层（测量常用）；含孔洞会保留嵌套层级，ParentIndex 指向已输出的父轮廓。',
  'contour.fromMask.approximation': '简化会压缩共线点；不简化保留每个边界像素。',
