  'output.database.maxPayloadBytes': '超过上限直接拒绝写入，而不是截断后落库。',
  'image.load.path': '图像文件或目录；path 端口接线时覆盖此参数。只能读取宿主授权的根目录内的路径。',
  'image.load.pathMode': '自动识别时，已存在的目录按帧序列处理，其余按单文件处理。',
