  'image.load.colorMode': 'preserve 保留原始位深与通道数（16 位仍是 16 位）；gray 转单通道；color 强制三通道。',
  'image.load.maxMegabytes': '解码前先按文件大小拦截，避免路径写错时耗尽内存。',
  'collection.detectionNumbers.field': '要提取的逐检测数值列；可选列缺失时计入 skipped，而不是当 0 参与统计。',
