  'image.synthetic.placementMode': '固定模式保持图案在基准位置；按序移动按“样本序号 × 位移/角度步长”生成位置；固定种子随机可复现；每次运行随机会重新生成位移和角度，并自动避开画幅边界。按序和固定种子模式越界时会把图案整体平移进画幅。',
