  'measure.caliperLine.sampleWidth': '投影宽度必须为奇数；输入偶数会向上调整为下一个奇数（例如 4→5）。沿预期边缘方向做灰度投影平均；增大可抑制局部噪声，但过大会混合相邻特征。',
  'measure.caliperLine.maxFitOutliers': '最多从拟合中排除几个残差超阈值的边缘点；设为 0 可关闭，且拟合至少要保留三个点。',
  'measure.caliperLine.fitOutlierThreshold': '点到拟合直线的垂直距离超过此值时才会被排除。提高阈值可减少误删真实边缘起伏。',
  'measure.caliperLine.maxFitError': '最终直线拟合的正交 RMS 误差超过此值时返回 found=false，候选结果仍会显示以便诊断。设为 0 可关闭质量门槛。',
  'match.shape.signatureSamples': '按角度采样外轮廓的数量。目标应关于质心呈星形，匹配按固定尺度进行。',
