  'match.shape.trainingAngleRangeDeg': '模型训练时覆盖的对称角度范围；例如 45 表示模型覆盖 −45°～+45°。修改后必须重新训练。',
  'match.shape.pyramidLevels': '0 表示自动选择层数；1～8 固定训练和搜索使用的金字塔层数。层数增加可缩短大图搜索时间，但可能丢失小特征。修改后必须重新训练。',
  'match.shape.searchAngleStartDeg': '本次搜索允许的最小角度；超出模型训练覆盖的部分会自动裁剪，无需重新训练。',
  'match.shape.searchAngleEndDeg': '本次搜索允许的最大角度；超出模型训练覆盖的部分会自动裁剪，无需重新训练。',
  'match.shape.searchScaleMinPercent': '本次搜索允许的最小尺寸，按训练目标尺寸的百分比表示；超出模型训练覆盖的部分会自动裁剪，无需重新训练。',
  'match.shape.searchScaleMaxPercent': '本次搜索允许的最大尺寸，按训练目标尺寸的百分比表示；超出模型训练覆盖的部分会自动裁剪，无需重新训练。',
  'match.shape.engine': 'managedChamfer 用模板图（templateRoi 裁剪、中心为原点）建轮廓模型并搜索倒角距离图，不使用已训练的原生模型；auto 仅在原生库不可用时回退到倒角匹配。',
  'match.shape.chamferTolerancePx': '仍计为模型轮廓已覆盖的最大边缘距离（像素）；调大更耐遮挡/模糊，但更容易接纳杂乱边缘。',
  'match.shape.chamferAngleStepDeg': '托管引擎的粗角度采样；局部精化会减半步长。角度仍是离散采样，不是连续求解。',
  'match.shape.chamferScaleStepPercent': '托管引擎在搜索最小/最大缩放之间的采样步长。',
  'match.shape.chamferMaxModelPoints': '模板边缘下采样后保留的轮廓点上限；点越多越慢，但形状细节越完整。',
  'match.shape.angleStepDeg': '训练角度步长。步长越小模型角度覆盖越细，但模型体积和训练时间会增加。修改后必须重新训练。',
  'measure.caliperCircle.angleStepDeg': '兼容步长模式的固定角度间隔。整圆不会重复采样起止射线；部分圆弧从起点按此间隔采样，终点未对齐时不会额外补点。',
  'match.shape.scaleTolerancePercent': '训练并搜索 100% 周围的对称均匀缩放范围；例如 10 表示 X/Y 同时在 90%～110%。设置 X/Y 独立容差后，本项不参与模型缩放范围。修改后必须重新训练。',
  'match.shape.scaleToleranceXPercent': '训练和搜索时允许的独立水平缩放范围；例如设为 10 表示 X 方向 90%～110%。X/Y 任一非零时采用独立轴缩放并覆盖均匀缩放设置。修改后必须重新训练。',
  'match.shape.scaleToleranceYPercent': '训练和搜索时允许的独立垂直缩放范围；例如设为 5 表示 Y 方向 95%～105%。X/Y 任一非零时采用独立轴缩放并覆盖均匀缩放设置。修改后必须重新训练。',
  'match.shape.maxClutterScore': '启用“杂乱 ROI”后，超过此阈值的候选位置会被底层形状模型拒绝。光照变化会影响杂乱分，需用实际场景调节。',
  'match.shape.maxDeformationPx': '允许匹配时轮廓特征相对模型局部移动的最大像素数。0 表示关闭；大于 0 时使用最小二乘位姿优化，无需重新训练，但容差过大会降低定位精度并增加误匹配。',
  'match.shape.scoreUsingClutter': '仅在训练过“杂乱 ROI”后可用。开启后按匹配分数 ×（1 − 杂乱分）调整最终分数；未调整的原生分数通过 nativeScore 输出。该调整是透明的近似策略，分数仍应按现场样本标定。',
  'match.shape.runtimeContrastThreshold': '匹配轮廓点处的平均梯度强度下限（0–255）；设为 0 时关闭。与训练时“最低特征对比度”分开，可随现场光照在运行时调节。',
  'match.shape.contrastFractionThreshold': '运行时特征对比度 ÷ 训练图特征对比度，范围 0–1；0 关闭。需保留无损原始训练图，用于剔除对比度低于训练样本的候选。',
  'match.shape.clutterContrast': '杂乱 ROI 内被计入的边缘最低对比度，不能低于“最低特征对比度”。修改后必须重新训练。',
  'match.shape.scaleStepPercent': '缩放采样步长；启用均匀或 X/Y 独立缩放容差时使用。步长越小，训练与搜索越慢。',
  'match.shape.ignorePolarity': '忽略边缘明暗方向，使模型能够匹配极性反转的同一轮廓。修改后必须重新训练。',
  'match.shape.minContrast': '训练时排除对比度低于此值的弱边缘，避免模型依赖噪声特征。修改后必须重新训练。',
  'match.shape.trainingMinSampleFraction': '复合模型仅保留至少出现在此比例训练样本中的轮廓特征。比例越高越能过滤偶发背景，但可能丢掉真实变化区域。修改后必须重新训练。',
  'match.shape.trainingFeatureTolerancePx': '匹配不同样本中的轮廓点时允许的最大距离。适当增大可容忍亚像素噪声和轻微形变；过大会把相邻边缘误合并。修改后必须重新训练。',
  'match.shape.trainingOriginX': '手动原点在完整训练图像中的 X 坐标（像素）；仅“训练原点”选择手动坐标时使用。',
  'match.shape.binarize': '只用于估算默认训练原点，不会对形状模型图像二值化。若未找到有效前景，回退到模型区域重心。',
  'match.shape.trainingOriginMode': '自动模式使用最大阈值区域的重心；找不到有效前景时回退到模型区域重心。形状模型本身始终使用原始灰度图。',
