  'image.threshold.threshold': '二值化阈值（0–255）：越高，保留的亮区域越少；目标偏暗时调低，偏亮时调高。',
  'image.threshold.mode': '手动适用于固定光照；自适应按局部窗口处理不均匀光照；Otsu 根据整幅图像直方图自动求全局阈值。',
