  'output.saveImage.filenameTemplate': '不含目录和扩展名。支持 {timestamp}/{date}/{runId}/{saveId}/{nodeId}/{result}/{partId}/{sequence}；result 需 pass，sequence 需非负整数输入并至少补齐 6 位。',
  'output.saveImage.partId': '仅模板使用 {partId} 时生效，partId 接线优先。非法文件名字符会替换并加内容指纹，避免不同标识被清洗成同名文件。',
  'output.saveImage.splitByDate': '按运行主机本地时间追加 yyyy-MM-dd 目录；与结果分类组合时目录为 日期/OK 或 日期/NG。',
  'output.saveImage.resultMode': '分类和筛选需连接 pass。只保存 OK/NG 时也放入对应结果目录；被筛掉的图像返回 saved=false，不编码、不创建文件或目录。',
  'output.saveImage.conflictPolicy': '另存时追加唯一标识，不自行维护全局流水号。文件发布时再次原子判断冲突；仅显式覆盖会替换已有文件。',
  'output.saveImage.overwrite': '旧流程覆盖别名；缺少 conflictPolicy 时兼容。新配置仅使用同名文件处理策略。',
  'output.saveImage.retryPolicy': '仅对原子发布前的临时文件写入与文件发布 IO 错误进行有限重试；编码、目录创建和参数错误直接报错。',
