  'color.classify.maxSamples': '采样像素硬上限；超过时明确失败而不是静默截断颜色分布。可提高上限或增大采样步长。',
  'color.classify.referenceColorsJson': '参考色 JSON 数组。Lab 模式写 {name,l,a,b,tolerance}；RGB 模式写 {name,r,g,b,tolerance}。省略 tolerance 时使用默认容差。',
