  'image.stitch.mode': 'panorama 适合任意重叠视角；scans 假设有序、近似平移的扫描图，通常更稳定。',
  'image.stitch.maxInputPixels': '所有输入的总像素预算。超过时在克隆和拼接前失败，避免全分辨率批次打满内存。',
  'recognition.aruco.dictionary': '必须与现场标记族一致；字典不匹配时不会给出错误 ID，而是检测不到。',
  'recognition.aruco.maxMarkers': '检测标记数量硬上限；超过时失败而不是静默丢弃标记。',
  'recognition.aruco.cornerRefinement': '可选亚像素角点细化。subpixel 提高干净标记的位姿稳定性；contour 可恢复模糊边缘但更慢。',
  'recognition.aruco.adaptiveThreshWinSizeMin': '自适应阈值最小窗口；小标记需要较小的最小值。',
