  'recognition.aruco.markerSize': 'solvePnP 使用的标记物理边长；仅在提供标定时读取。',
  'recognition.aruco.markerSizeUnit': '标记尺寸与输出三维变换的单位，1..16 个字符，例如 mm 或 m。',
  'recognition.aruco.calibrationJson': '可接 calibration.cameraIntrinsics 的 CameraCalibrationModel JSON；接线优先。没有标定时仍可检测，但 poseAvailable=false。鱼眼/远心模型不做位姿。',
  'calibration.charuco.squaresX': '棋盘沿 X 方向的方格数，必须与打印的 ChArUco 板一致。',
  'calibration.charuco.squaresY': '棋盘沿 Y 方向的方格数，必须与打印的 ChArUco 板一致。',
  'calibration.charuco.squareLengthMm': '一个棋盘方格的物理边长，用于板坐标系和标定物点。',
