  'script.csharp.source': 'C# 脚本体。使用 Input.Number/Integer/Boolean/Text/Numbers/Points、Image（Mat）、Output.Result/Number/Text/Boolean/Json/Image、Log 与 Fail；顶层 return 在 Output.Result 未设置时作为 result。工作 Mat 请用 using 块或显式 Dispose；当前 Roslyn 脚本解析器不接受顶层 using var 声明。',
  'script.csharp.timeoutMs': '墙钟预算，在注入的循环/函数入口 tick 处检查；不会中断不主动让出的原生 OpenCV 或 BCL 长调用。',
  'script.csharp.maxTicks': '循环和函数入口的最大 tick 数；超出后脚本停止。',
  'script.csharp.maxOutputBytes': 'Output.Text/Json 的最大 UTF-8 字节数；结构化数据必须是合法 JSON。',
  'script.csharp.maxImagePixels': '输入/输出 Mat 的最大像素数；超限会拒绝，避免占满宿主内存。',
  'match.feature.templatePath': '未连接 template 端口时使用的模板图路径（绝对路径，或相对宿主工作目录）。连接了 template 端口时以端口为准。',
  'match.feature.detector': 'SIFT 抗大旋转/缩放/轻度遮挡但更慢；ORB 快数倍，适合节拍高、纹理充足的平面件。',
  'match.feature.maxFeatures': '每张图保留的关键点上限。大图或重复纹理可调高，代价是时间与内存；默认 2000 足够多数产线图。',
  'match.feature.contrastThreshold': 'SIFT 对比度门限。低对比件调到 0.01，噪声多时调到 0.08 抑制噪点关键点。ORB 不读该值。',
  'match.feature.matchRatio': '最近邻与次近邻距离比门限：只有明显优于次优的匹配才保留。0 关闭比值筛选；调小更严（匹配更少但更干净）。',
  'match.feature.transformType': '相似变换所需内点最少、最稳，适合抓取对位；仿射可吸收来料拉伸；单应能处理斜视但放大噪声。',
  'match.feature.ransacReprojThresholdPx': '对应点落在模型该距离内即算内点。一般取关键点定位误差量级（2~4 像素）。',
  'match.feature.minMatches': '进入 RANSAC 前要求的比值筛选后匹配数，低于它直接返回 found=false（reason=too-few-matches）。',
  'match.feature.minInliers': '有效结果所需的最少 RANSAC 内点数。过低会让偶然对齐通过，纹理件常用 6~10。',
  'match.feature.minInlierRatio': '内点/匹配数的最低比例。比例过低通常说明命中了重复纹理而不是真目标。',
  'match.feature.angleRangeDeg': '允许的旋转半宽，超出即判 found=false。180 表示不限制。',
  'match.feature.scaleMinPercent': '允许的最小尺度（相对模板）。低于它返回 found=false（reason=scale-out-of-range）。',
  'match.feature.scaleMaxPercent': '允许的最大尺度（相对模板），不得小于最小尺度。',
  'tolerance.datum.datumName': '写进 datumJson、叠加层与报表的基准标号，图纸常用 A/B/C。',
  'tolerance.datum.flipAxis': '把 +X 方向反过来。拟合直线本身没有极性，图纸 X 轴方向相反时打开它。',
  'tolerance.datum.unit': '仅作标注，不做换算（1..16 字符）。上游坐标已标定成 mm 时填 mm，报表与追溯记录才对得上。',
  'tolerance.position.basicX': '沿基准 X 轴的框式基本尺寸。基本尺寸是理论精确值，本身不带公差。',
  'tolerance.position.basicY': '沿基准 Y 轴的框式基本尺寸。',
  'tolerance.position.zoneType': '孔/轴位置度通常用圆形公差带，实测值按 2×径向误差报；矩形带则逐轴对各自的半宽判定。',
  'tolerance.position.diameterTolerance': '圆形公差带的直径，即框格里的 Ø 值。填 0 关闭判定，utilization 输出 0。',
  'tolerance.position.toleranceX': '矩形公差带在 X 向的半宽。填 0 表示该轴不参与判定。',
  'tolerance.position.toleranceY': '矩形公差带在 Y 向的半宽。填 0 表示该轴不参与判定。',
  'tolerance.position.mmcBonus': '把最大实体补偿（实测尺寸相对 MMC 的偏离量）加到公差上。需要实测尺寸：size 端口或 circle 输入。',
  'tolerance.position.mmcSize': '最大实体状态下的要素尺寸：孔取最小允许直径，轴取最大允许直径。开启补偿时必须 > 0。',
  'tolerance.position.featureType': '决定补偿方向：孔越大于 MMC 补偿越多，轴越小于 MMC 补偿越多。',
  'tolerance.position.unit': '仅作标注，不做换算（1..16 字符）。上游坐标已标定时填 mm。',
  'tolerance.runout.mode': 'radial 量到基准轴的距离，对应圆柱面圆跳动；axial 量沿基准轴的坐标，对应端面全跳动。',
  'tolerance.runout.tolerance': '允许的最大读数差（FIM = 最大读数 − 最小读数）。填 0 关闭判定。',
  'tolerance.runout.minCoverageDeg': '仅 radial 模式：采样弧段覆盖角小于该值时判为无效。覆盖角 = 360° − 最大角度缺口；填 0 关闭。只测半圈的跳动永远看起来比实际好。',
  'tolerance.runout.unit': '仅作标注，不做换算（1..16 字符）。上游坐标已标定时填 mm。',
  'image.convolve.kernelJson': '按行书写的 JSON 数组，例如 [[-1,-1,-1],[-1,8,-1],[-1,-1,-1]] 是边缘增强核。最大 31×31，数值限 ±10000，每行长度必须一致。',
  'image.convolve.normalize': '用核元素之和做归一化，让均匀区亮度保持不变。边缘/差分核的和通常为 0，必须关掉本项，否则节点直接报错而不是给出全黑图。',
  'image.convolve.delta': '卷积后逐像素加上的常数。边缘图有负值时用正值抬起来，避免直接截成黑边。',
  'image.convolve.anchorX': '与输出像素对齐的核列号。-1 表示几何中心；非对称核（例如方向性脊线检测）需要显式指定锚点。',
  'image.convolve.anchorY': '与输出像素对齐的核行号。-1 表示几何中心。',
  'image.convolve.borderType': '图像外像素的外推方式。测量边缘优先用 Reflect 101，偏置最小；常数 0 会让边界变暗，只在明确补零时使用。',
  'image.fftFilter.filter': '带阻是纹理/摩尔纹的主力：把周期落在带内的图案挖掉，其余原样保留；带通只留该周期；低通留大结构，高通留细节。',
  'image.fftFilter.wavelengthMinPx': '带内最短周期（像素）——想被去掉或保留的图案周期。3 表示"每 3 个像素一个周期"，即 1/3 cycles/pixel。',
  'image.fftFilter.wavelengthMaxPx': '带内最长周期（像素）。带通/带阻时必须不小于最小波长；数值越大越靠近直流（粗结构）端。',
  'image.fftFilter.directionDeg': '频带中心方向，图像坐标（0 = 横向条纹，90 = 竖向条纹）。频谱共轭对称，0 与 180 描述同一条带。',
  'image.fftFilter.directionWidthDeg': '频带的角宽。0 表示去掉方向窗口、按旋转对称处理；15~30 度专治只朝一个方向走的拉丝/车纹/织造纹理。',
  'image.fftFilter.maskBlurPx': '对频率掩码做高斯软化（单位：频谱像素）。0 是硬边（最锐利、振铃最重）；0.5~2 用一点选择性换掉强边缘周围的振铃。',
  'image.fftFilter.keepDc': '把零频增益强制拉回 1，让高通/带阻之后的平均亮度不跑。只在"绝对亮度无所谓、要零均值结果"时关掉。',
  'image.fftFilter.outputMode': '滤波结果是拿去检的干净图；被滤掉的成分单独输出，是调波长带最快的办法。零均值残差在 8/16 位输出时会把负半周截掉，所以整型输入会把各通道均值加回去（浮点输入保持纯差值）。',
  'image.fftFilter.maxPixels': '补零后 FFT 尺寸的预算（宽高都会向上取到快速 DFT 尺寸）。FFT 内存随补零面积增长且逐通道执行，超预算直接报尺寸错误，而不是把内存吃光。',
